"""Thread brands from embroidery/threads.json (generated by scripts/generate-threads.py).

Other charts live with the editor (public/threads/); like lib/threads.ts, the compiler checks
Brother references against the chart and other brands' references for shape only.
"""
import json
from pathlib import Path

DATA = json.loads(Path(__file__).with_suffix(".json").read_text())
BRANDS = DATA["brands"]
LABELS = {b["id"]: b["label"] for b in BRANDS}
BY_LABEL = {b["label"]: b["id"] for b in BRANDS}
BROTHER = {code: (name, color) for code, name, color in DATA["brother"]}


def valid_thread(value, color):
    if not isinstance(value, dict) or value.get("brand") not in LABELS or not isinstance(color, str):
        return False
    code, name = value.get("code"), value.get("name")
    if not (isinstance(code, str) and 0 < len(code) <= 24 and isinstance(name, str) and len(name) <= 60):
        return False
    return value["brand"] != "brother" or BROTHER.get(code) == (name, color.lower())
